import WebSocketFactory, { WebSocketLike } from './lib/websocket-factory'

import {
  CONNECTION_STATE,
  CONNECTION_REFRESH_RETRY_MS,
  DEFAULT_CONNECTION_REFRESH_JITTER_MS,
  DEFAULT_TIMEOUT,
  DEFAULT_VSN,
  STANDBY_CONNECT_TIMEOUT_MS,
  VSN_1_0_0,
  VSN_2_0_0,
} from './lib/constants'

import Serializer from './lib/serializer'
import { httpEndpointURL } from './lib/transformers'
import RealtimeChannel from './RealtimeChannel'
import type { RealtimeChannelOptions } from './RealtimeChannel'
import SocketAdapter from './phoenix/socketAdapter'
import type {
  Message,
  SocketOptions,
  HeartbeatCallback,
  Encode,
  Decode,
  Timer,
  Vsn,
} from './phoenix/types'

type Fetch = typeof fetch

export type LogLevel = 'info' | 'warn' | 'error' | (string & {})

export type RealtimeMessage = {
  topic: string
  event: string
  payload: any
  ref: string
  join_ref?: string
}

export type RealtimeRemoveChannelResponse = 'ok' | 'timed out' | 'error' | (string & {})
export type HeartbeatStatus = 'sent' | 'ok' | 'error' | 'timeout' | 'disconnected' | (string & {})
export type HeartbeatTimer = ReturnType<typeof setTimeout> | undefined

// Connection-related constants
const CONNECTION_TIMEOUTS = {
  HEARTBEAT_INTERVAL: 25000,
  RECONNECT_DELAY: 10,
  HEARTBEAT_TIMEOUT_FALLBACK: 100,
} as const

const RECONNECT_INTERVALS = [1000, 2000, 5000, 10000] as const
const DEFAULT_RECONNECT_FALLBACK = 10000

/**
 * Minimal WebSocket constructor interface that RealtimeClient can work with.
 * Supply a compatible implementation (native WebSocket, `ws`, etc) when running outside the browser.
 */
export interface WebSocketLikeConstructor {
  new (address: string | URL, subprotocols?: string | string[] | undefined): WebSocketLike
  // Allow additional properties that may exist on WebSocket constructors
  [key: string]: any
}

export type RealtimeClientOptions = {
  transport?: WebSocketLikeConstructor
  timeout?: number
  heartbeatIntervalMs?: number
  heartbeatCallback?: (status: HeartbeatStatus, latency?: number) => void
  vsn?: string
  logger?: (kind: string, msg: string, data?: any) => void
  encode?: Encode<void>
  decode?: Decode<void>
  reconnectAfterMs?: (tries: number) => number
  headers?: { [key: string]: string }
  params?: { [key: string]: any }
  //Deprecated: Use it in favour of correct casing `logLevel`
  log_level?: LogLevel
  logLevel?: LogLevel
  fetch?: Fetch
  worker?: boolean
  workerUrl?: string
  accessToken?: () => Promise<string | null>
  disconnectOnEmptyChannelsAfterMs?: number
  /**
   * Refresh the WebSocket before this age (ms) by opening a standby connection,
   * rejoining all subscribed channels, then closing the old socket.
   * `0` or omitted disables dual-connection hot-cut. CloudBase `createRealtimeClient`
   * defaults this to 270000 to stay under a 300s gateway max-lifetime.
   */
  connectionMaxAgeMs?: number
  /**
   * Random extra delay (ms) added on top of `connectionMaxAgeMs` when scheduling
   * a refresh. Defaults to 20000. Pass `0` in tests for a deterministic timer.
   */
  connectionRefreshJitterMs?: number
  /**
   * Called before any transport connect (initial open and standby refresh).
   * Use this to refresh query params such as `apikey` so both sockets share the same hook.
   */
  beforeTransportConnect?: () => Promise<void>
  /**
   * Storage compatible object used by the underlying socket for longpoll fallback history.
   * Provide a custom implementation in environments where reading `globalThis.sessionStorage`
   * throws (sandboxed iframes, in-app webviews, "block third-party storage" privacy modes).
   * Defaults to `globalThis.sessionStorage` when accessible, otherwise an in-memory store.
   */
  sessionStorage?: Storage
}

function createMemorySessionStorage(): Storage {
  const store = new Map<string, string>()
  return {
    get length() {
      return store.size
    },
    clear() {
      store.clear()
    },
    getItem(key: string) {
      return store.has(key) ? (store.get(key) as string) : null
    },
    key(index: number) {
      return Array.from(store.keys())[index] ?? null
    },
    removeItem(key: string) {
      store.delete(key)
    },
    setItem(key: string, value: string) {
      store.set(key, String(value))
    },
  }
}

function resolveSessionStorage(): Storage {
  try {
    if (typeof globalThis !== 'undefined' && globalThis.sessionStorage) {
      return globalThis.sessionStorage
    }
  } catch {
    // Property access on `sessionStorage` itself throws in restricted-storage browsers.
  }
  return createMemorySessionStorage()
}

const WORKER_SCRIPT = `
  addEventListener("message", (e) => {
    if (e.data.event === "start") {
      setInterval(() => postMessage({ event: "keepAlive" }), e.data.interval);
    }
  });`

export default class RealtimeClient {
  /** @internal */
  socketAdapter: SocketAdapter
  channels: RealtimeChannel[] = new Array()

  accessTokenValue: string | null = null
  accessToken: (() => Promise<string | null>) | null = null
  apiKey: string | null = null

  httpEndpoint: string = ''
  /** @deprecated headers cannot be set on websocket connections */
  headers?: { [key: string]: string } = {}
  params?: { [key: string]: string } = {}

  ref: number = 0

  logLevel?: LogLevel

  fetch: Fetch
  worker?: boolean
  workerUrl?: string
  workerRef?: Worker

  serializer: Serializer = new Serializer()

  get endPoint() {
    return this.socketAdapter.endPoint
  }

  get timeout() {
    return this.socketAdapter.timeout
  }

  get transport() {
    return this.socketAdapter.transport
  }

  get heartbeatCallback() {
    return this.socketAdapter.heartbeatCallback
  }

  get heartbeatIntervalMs() {
    return this.socketAdapter.heartbeatIntervalMs
  }

  get heartbeatTimer() {
    if (this.worker) {
      return this._workerHeartbeatTimer
    }
    return this.socketAdapter.heartbeatTimer
  }

  get pendingHeartbeatRef() {
    if (this.worker) {
      return this._pendingWorkerHeartbeatRef
    }
    return this.socketAdapter.pendingHeartbeatRef
  }

  get reconnectTimer(): Timer {
    return this.socketAdapter.reconnectTimer
  }

  get vsn(): Vsn {
    return this.socketAdapter.vsn
  }

  get encode() {
    return this.socketAdapter.encode
  }

  get decode() {
    return this.socketAdapter.decode
  }

  get reconnectAfterMs() {
    return this.socketAdapter.reconnectAfterMs
  }

  get sendBuffer() {
    return this.socketAdapter.sendBuffer
  }

  get stateChangeCallbacks(): {
    open: [string, Function][]
    close: [string, Function][]
    error: [string, Function][]
    message: [string, Function][]
  } {
    return this.socketAdapter.stateChangeCallbacks
  }

  private _manuallySetToken: boolean = false
  private _authPromise: Promise<void> | null = null
  private _authGeneration: number = 0
  private _workerHeartbeatTimer: HeartbeatTimer = undefined
  private _pendingWorkerHeartbeatRef: string | null = null
  private _pendingDisconnectTimer: ReturnType<typeof setTimeout> | null = null
  private _disconnectOnEmptyChannelsAfterMs: number = 0
  private _endPoint: string = ''
  private _socketOptions: SocketOptions = {}
  private _beforeTransportConnect?: () => Promise<void>
  private _openingActive = false
  private _handlersAdapter: SocketAdapter | null = null
  private _standbyAdapter: SocketAdapter | null = null
  private _rotating = false
  private _cutoverStarted = false
  private _refreshTimer: ReturnType<typeof setTimeout> | null = null
  private _rotateRetryTimer: ReturnType<typeof setTimeout> | null = null
  /** @internal */
  connectionMaxAgeMs = 0
  /** @internal */
  connectionRefreshJitterMs = DEFAULT_CONNECTION_REFRESH_JITTER_MS

  /**
   * Initializes the Socket.
   *
   * @param endPoint The string WebSocket endpoint, ie, "ws://example.com/socket", "wss://example.com", "/socket" (inherited host & protocol)
   * @param options.transport The Websocket Transport, for example WebSocket. This can be a custom implementation
   * @param options.timeout The default timeout in milliseconds to trigger push timeouts.
   * @param options.params The optional params to pass when connecting.
   * @param options.headers Deprecated: headers cannot be set on websocket connections and this option will be removed in the future.
   * @param options.heartbeatIntervalMs The millisec interval to send a heartbeat message.
   * @param options.heartbeatCallback The optional function to handle heartbeat status and latency.
   * @param options.logger The optional function for specialized logging, ie: logger: (kind, msg, data) => { console.log(`${kind}: ${msg}`, data) }
   * @param options.logLevel Sets the log level for Realtime
   * @param options.encode The function to encode outgoing messages. Defaults to JSON: (payload, callback) => callback(JSON.stringify(payload))
   * @param options.decode The function to decode incoming messages. Defaults to Serializer's decode.
   * @param options.reconnectAfterMs he optional function that returns the millsec reconnect interval. Defaults to stepped backoff off.
   * @param options.worker Use Web Worker to set a side flow. Defaults to false.
   * @param options.workerUrl The URL of the worker script. Defaults to https://realtime.supabase.com/worker.js that includes a heartbeat event call to keep the connection alive.
   * @param options.vsn The protocol version to use when connecting. Supported versions are "1.0.0" and "2.0.0". Defaults to "2.0.0".
   * @param options.connectionMaxAgeMs Refresh the socket before this age by hot-cutting to a standby connection. Disabled by default.
   * @param options.connectionRefreshJitterMs Random extra delay added to `connectionMaxAgeMs`. Defaults to 20000.
   * @param options.beforeTransportConnect Hook invoked before opening the active or standby transport.
   *
   * @category Realtime
   *
   * @example Using supabase-js (recommended)
   * ```ts
   * import { createClient } from '@supabase/supabase-js'
   *
   * const supabase = createClient('https://xyzcompany.supabase.co', 'your-publishable-key')
   * const channel = supabase.channel('room1')
   * channel
   *   .on('broadcast', { event: 'cursor-pos' }, (payload) => console.log(payload))
   *   .subscribe()
   * ```
   *
   * @example Standalone import for bundle-sensitive environments
   * ```ts
   * import RealtimeClient from '@cloudbase/realtime-js'
   *
   * const client = new RealtimeClient('https://xyzcompany.supabase.co/realtime/v1', {
   *   params: { apikey: 'your-publishable-key' },
   * })
   * client.connect()
   * ```
   */
  constructor(endPoint: string, options?: RealtimeClientOptions) {
    // Validate required parameters
    if (!options?.params?.apikey) {
      throw new Error('API key is required to connect to Realtime')
    }
    this.apiKey = options.params.apikey

    const socketAdapterOptions = this._initializeOptions(options)

    this._endPoint = endPoint
    this._socketOptions = socketAdapterOptions
    this.socketAdapter = this._createSocketAdapter()
    this.httpEndpoint = httpEndpointURL(endPoint)

    this.fetch = this._resolveFetch(options?.fetch)
  }

  /**
   * Connects the socket, unless already connected.
   *
   * @category Realtime
   */
  connect(): void {
    // Skip if already connecting, disconnecting, or connected
    if (
      this.isConnecting() ||
      this.isDisconnecting() ||
      this.isConnected() ||
      this._openingActive
    ) {
      return
    }

    // Trigger auth if needed and not already in progress
    // This ensures auth is called for standalone RealtimeClient usage
    // while avoiding race conditions with SupabaseClient's immediate setAuth call
    if (this.accessToken && !this._authPromise) {
      this._setAuthSafely('connect')
    }

    if (this._beforeTransportConnect) {
      this._openingActive = true
      void this._openActiveSocket().catch((error) => {
        this.log('error', 'failed to open socket', error)
      })
      return
    }

    this._setupConnectionHandlers()

    try {
      this.socketAdapter.connect()
    } catch (error) {
      const errorMessage = (error as Error).message
      throw new Error(`WebSocket not available: ${errorMessage}`)
    }

    this._handleNodeJsRaceCondition()
  }

  /**
   * Returns the URL of the websocket.
   * @returns string The URL of the websocket.
   *
   * @category Realtime
   */
  endpointURL(): string {
    return this.socketAdapter.endPointURL()
  }

  /**
   * Disconnects the socket.
   *
   * @param code A numeric status code to send on disconnect.
   * @param reason A custom reason for the disconnect.
   *
   * @category Realtime
   */
  async disconnect(code?: number, reason?: string) {
    this._cancelPendingDisconnect()
    this._cancelConnectionRefresh()
    this._cancelRotateRetry()
    this._rotating = false
    this._cutoverStarted = false

    const standby = this._standbyAdapter
    this._standbyAdapter = null

    if (this.isDisconnecting()) {
      if (standby) {
        await standby.disconnect(() => {}, 1000, 'connection refresh abort')
      }
      return 'ok'
    }
    const result = await this.socketAdapter.disconnect(
      () => {
        clearInterval(this._workerHeartbeatTimer)
        this._terminateWorker()
      },
      code,
      reason
    )
    if (standby) {
      await standby.disconnect(() => {}, 1000, 'connection refresh abort')
    }
    return result
  }

  /**
   * Returns all created channels
   *
   * @category Realtime
   */
  getChannels(): RealtimeChannel[] {
    return this.channels
  }

  /**
   * Unsubscribes, removes and tears down a single channel
   * @param channel A RealtimeChannel instance
   *
   * @category Realtime
   */
  async removeChannel(channel: RealtimeChannel): Promise<RealtimeRemoveChannelResponse> {
    const status = await channel.unsubscribe()

    if (status === 'ok') {
      channel.teardown()
    }

    return status
  }

  /**
   * Unsubscribes, removes and tears down all channels
   *
   * @category Realtime
   */
  async removeAllChannels(): Promise<RealtimeRemoveChannelResponse[]> {
    const promises = this.channels.map(async (channel) => {
      const result = await channel.unsubscribe()
      channel.teardown()
      return result
    })

    const result = await Promise.all(promises)
    await this.disconnect()
    return result
  }

  /**
   * Logs the message.
   *
   * For customized logging, `this.logger` can be overridden in Client constructor.
   *
   * @category Realtime
   */
  log(kind: string, msg: string, data?: any) {
    this.socketAdapter.log(kind, msg, data)
  }

  /**
   * Returns true if a custom `logger` has been configured on this client.
   *
   * @category Realtime
   */
  hasLogger(): boolean {
    return this.socketAdapter.hasLogger()
  }

  /**
   * Returns the current state of the socket.
   *
   * @category Realtime
   */
  connectionState() {
    return this.socketAdapter.connectionState() || CONNECTION_STATE.closed
  }

  /**
   * Returns `true` is the connection is open.
   *
   * @category Realtime
   */
  isConnected(): boolean {
    return this.socketAdapter.isConnected()
  }

  /**
   * Returns `true` if the connection is currently connecting.
   *
   * @category Realtime
   */
  isConnecting(): boolean {
    return this.socketAdapter.isConnecting()
  }

  /**
   * Returns `true` if the connection is currently disconnecting.
   *
   * @category Realtime
   */
  isDisconnecting(): boolean {
    return this.socketAdapter.isDisconnecting()
  }

  /**
   * Creates (or reuses) a {@link RealtimeChannel} for the provided topic.
   *
   * Topics are automatically prefixed with `realtime:` to match the Realtime service.
   * If a channel with the same topic already exists it will be returned instead of creating
   * a duplicate connection.
   *
   * @category Realtime
   */
  channel(topic: string, params: RealtimeChannelOptions = { config: {} }): RealtimeChannel {
    const realtimeTopic = `realtime:${topic}`
    const exists = this.getChannels().find((c: RealtimeChannel) => c.topic === realtimeTopic)

    if (!exists) {
      const chan = new RealtimeChannel(`realtime:${topic}`, params, this)
      this._cancelPendingDisconnect()
      this.channels.push(chan)

      return chan
    } else {
      return exists
    }
  }

  /**
   * Push out a message if the socket is connected.
   *
   * If the socket is not connected, the message gets enqueued within a local buffer, and sent out when a connection is next established.
   *
   * @category Realtime
   */
  push(data: RealtimeMessage): void {
    this.socketAdapter.push(data)
  }

  /**
   * Caches the access token used for HTTP `Authorization` and the next
   * WebSocket `apikey` query param. CloudBase authenticates the socket on
   * handshake; `phx_join` and in-band `access_token` events do not carry it.
   *
   * If param is null it will use the `accessToken` callback function or the token set on the client.
   *
   * On callback used, it will set the value of the token internal to the client.
   *
   * When a token is explicitly provided AND no `accessToken` callback is configured,
   * it will be preserved across channel operations (including removeChannel and
   * resubscribe) and the client stays in manual-token mode.
   *
   * When an `accessToken` callback IS configured, the callback is the source of truth:
   * the client remains in callback mode and continues to refresh from it on heartbeat,
   * even after a bootstrap/override `setAuth(token)` call.
   *
   * @param token A JWT string to override the token set on the client.
   *
   * @example Setting the authorization header
   * // Use a manual token (preserved across resubscribes when no accessToken callback is set)
   * client.realtime.setAuth('my-custom-jwt')
   *
   * // Switch back to using the accessToken callback
   * client.realtime.setAuth()
   *
   * @category Realtime
   */
  async setAuth(token: string | null = null): Promise<void> {
    const authGeneration = ++this._authGeneration
    const authPromise = this._performAuth(token, authGeneration)
    if (authGeneration === this._authGeneration) {
      this._authPromise = authPromise
    }
    try {
      await authPromise
    } finally {
      if (this._authPromise === authPromise) {
        this._authPromise = null
      }
    }
  }

  /**
   * Returns true if the current access token was explicitly set via setAuth(token),
   * false if it was obtained via the accessToken callback.
   * @internal
   */
  _isManualToken(): boolean {
    return this._manuallySetToken
  }

  /**
   * Sends a heartbeat message if the socket is connected.
   *
   * @category Realtime
   */
  async sendHeartbeat() {
    this.socketAdapter.sendHeartbeat()
  }

  /**
   * Sets a callback that receives lifecycle events for internal heartbeat messages.
   * Useful for instrumenting connection health (e.g. sent/ok/timeout).
   *
   * @category Realtime
   */
  onHeartbeat(callback: HeartbeatCallback) {
    this.socketAdapter.heartbeatCallback = this._wrapHeartbeatCallback(callback)
  }

  /**
   * Use either custom fetch, if provided, or default fetch to make HTTP requests
   *
   * @internal
   */
  _resolveFetch = (customFetch?: Fetch): Fetch => {
    if (customFetch) {
      return (...args) => customFetch(...args)
    }
    return (...args) => {
      if (typeof fetch === 'undefined') {
        throw new Error(
          'httpSend() requires a fetch implementation. Pass options.fetch, or use app.realtime() after registering a platform adapter that provides reqClass.'
        )
      }
      return fetch(...args)
    }
  }

  /**
   * Return the next message ref, accounting for overflows
   *
   * @internal
   */
  _makeRef(): string {
    return this.socketAdapter.makeRef()
  }

  /**
   * Removes a channel from RealtimeClient
   *
   * @param channel An open subscription.
   *
   * @internal
   */
  _remove(channel: RealtimeChannel) {
    this.channels = this.channels.filter((c) => c.topic !== channel.topic)
    if (this.channels.length === 0) {
      this.log('transport', 'no channels remaining, scheduling disconnect')
      this._cancelConnectionRefresh()
      this._cancelRotateRetry()
      void this._abortRotate()
      this._schedulePendingDisconnect()
    }
  }


  /** @internal */
  private _schedulePendingDisconnect() {
    this._cancelPendingDisconnect()
    if (this._disconnectOnEmptyChannelsAfterMs === 0) {
      this.log('transport', 'disconnecting immediately - no channels')
      this.disconnect()
      return
    }
    this._pendingDisconnectTimer = setTimeout(() => {
      this._pendingDisconnectTimer = null
      if (this.channels.length === 0) {
        this.log('transport', 'deferred disconnect fired - no channels, disconnecting')
        this.disconnect()
      }
    }, this._disconnectOnEmptyChannelsAfterMs)
    this.log(
      'transport',
      `deferred disconnect scheduled in ${this._disconnectOnEmptyChannelsAfterMs}ms`
    )
  }

  /** @internal */
  private _cancelPendingDisconnect() {
    if (this._pendingDisconnectTimer !== null) {
      this.log('transport', 'pending disconnect cancelled - channel activity detected')
      clearTimeout(this._pendingDisconnectTimer)
      this._pendingDisconnectTimer = null
    }
  }

  /**
   * Perform the actual auth operation
   * @internal
   */
  private async _performAuth(token: string | null, authGeneration: number): Promise<void> {
    let tokenToSend: string | null
    let isManualToken = false

    if (token) {
      tokenToSend = token
      // Track if this is a manually-provided token
      isManualToken = true
    } else if (this.accessToken) {
      // Call the accessToken callback to get fresh token
      try {
        tokenToSend = await this.accessToken()
      } catch (e) {
        this.log('error', 'Error fetching access token from callback', e)
        // Fall back to cached value if callback fails
        tokenToSend = this.accessTokenValue
      }
    } else {
      tokenToSend = this.accessTokenValue
    }

    if (authGeneration !== this._authGeneration) {
      return
    }

    // Track whether this token was manually set or fetched via callback.
    // The callback is the source of truth for token refresh
    if (this.accessToken) {
      this._manuallySetToken = false
    } else if (isManualToken) {
      this._manuallySetToken = true
    }

    if (this.accessTokenValue != tokenToSend) {
      this.accessTokenValue = tokenToSend
    }
  }

  /**
   * Wait for any in-flight auth operations to complete
   * @internal
   */
  private async _waitForAuthIfNeeded(): Promise<void> {
    if (this._authPromise) {
      await this._authPromise
    }
  }

  /**
   * Safely call setAuth with standardized error handling
   * @internal
   */
  private _setAuthSafely(context = 'general'): void {
    // Only refresh auth if using callback-based tokens
    if (!this._isManualToken()) {
      this.setAuth().catch((e) => {
        this.log('error', `Error setting auth in ${context}`, e)
      })
    }
  }

  /** @internal */
  private _setupConnectionHandlers(): void {
    if (this._handlersAdapter === this.socketAdapter) {
      return
    }
    this._handlersAdapter = this.socketAdapter
    const adapter = this.socketAdapter

    adapter.onOpen(() => {
      if (this.socketAdapter !== adapter) {
        return
      }
      const authPromise =
        this._authPromise ||
        (this.accessToken && !this.accessTokenValue ? this.setAuth() : Promise.resolve())

      authPromise.catch((e) => {
        this.log('error', 'error waiting for auth on connect', e)
      })

      if (this.worker && !this.workerRef) {
        this._startWorkerHeartbeat()
      }

      this._scheduleConnectionRefresh()
    })
    adapter.onClose(() => {
      if (this.socketAdapter !== adapter) {
        return
      }
      if (this.worker && this.workerRef) {
        this._terminateWorker()
      }
      if (this._rotating && !this._cutoverStarted) {
        this.log('transport', 'active socket closed during refresh, aborting standby')
        void this._abortRotate()
      }
      if (!this._rotating) {
        this._cancelConnectionRefresh()
      }
    })
    adapter.onMessage((message: Message<any>) => {
      if (this.socketAdapter !== adapter) {
        return
      }
      if (message.ref && message.ref === this._pendingWorkerHeartbeatRef) {
        this._pendingWorkerHeartbeatRef = null
      }
    })
  }

  /** @internal */
  private _handleNodeJsRaceCondition() {
    if (this.socketAdapter.isConnected()) {
      // hack: ensure onConnOpen is called
      this.socketAdapter.getSocket().onConnOpen()
    }
  }

  /** @internal */
  private _wrapHeartbeatCallback(heartbeatCallback?: HeartbeatCallback): HeartbeatCallback {
    return (status, latency) => {
      if (status === 'disconnected') return
      if (status == 'sent') this._setAuthSafely()
      if (heartbeatCallback) heartbeatCallback(status, latency)
    }
  }

  /** @internal */
  private _startWorkerHeartbeat() {
    if (this.workerUrl) {
      this.log('worker', `starting worker for from ${this.workerUrl}`)
    } else {
      this.log('worker', `starting default worker`)
    }
    const objectUrl = this._workerObjectUrl(this.workerUrl!)
    this.workerRef = new Worker(objectUrl)
    this.workerRef.onerror = (error) => {
      this.log('worker', 'worker error', (error as ErrorEvent).message)
      this._terminateWorker()
      this.disconnect()
    }
    this.workerRef.onmessage = (event) => {
      if (event.data.event === 'keepAlive') {
        this.sendHeartbeat()
      }
    }
    this.workerRef.postMessage({
      event: 'start',
      interval: this.heartbeatIntervalMs,
    })
  }

  /**
   * Terminate the Web Worker and clear the reference
   * @internal
   */
  private _terminateWorker(): void {
    if (this.workerRef) {
      this.log('worker', 'terminating worker')
      this.workerRef.terminate()
      this.workerRef = undefined
    }
  }

  /** @internal */
  private _workerObjectUrl(url: string | undefined): string {
    let result_url: string
    if (url) {
      result_url = url
    } else {
      const blob = new Blob([WORKER_SCRIPT], { type: 'application/javascript' })
      result_url = URL.createObjectURL(blob)
    }
    return result_url
  }

  /**
   * Initialize socket options with defaults
   * @internal
   */
  private _initializeOptions(options?: RealtimeClientOptions): SocketOptions {
    this.worker = options?.worker ?? false
    this.accessToken = options?.accessToken ?? null
    this.connectionMaxAgeMs = options?.connectionMaxAgeMs ?? 0
    this.connectionRefreshJitterMs =
      options?.connectionRefreshJitterMs ?? DEFAULT_CONNECTION_REFRESH_JITTER_MS
    this._beforeTransportConnect = options?.beforeTransportConnect

    const result: SocketOptions = {}
    result.timeout = options?.timeout ?? DEFAULT_TIMEOUT
    result.heartbeatIntervalMs =
      options?.heartbeatIntervalMs ?? CONNECTION_TIMEOUTS.HEARTBEAT_INTERVAL

    this._disconnectOnEmptyChannelsAfterMs =
      options?.disconnectOnEmptyChannelsAfterMs ??
      2 * (options?.heartbeatIntervalMs ?? CONNECTION_TIMEOUTS.HEARTBEAT_INTERVAL)

    // @ts-ignore - mismatch between phoenix and supabase
    result.transport = options?.transport ?? WebSocketFactory.getWebSocketConstructor()
    result.params = options?.params
    result.logger = options?.logger
    result.heartbeatCallback = this._wrapHeartbeatCallback(options?.heartbeatCallback)
    result.sessionStorage = options?.sessionStorage ?? resolveSessionStorage()
    result.reconnectAfterMs =
      options?.reconnectAfterMs ??
      ((tries: number) => {
        return RECONNECT_INTERVALS[tries - 1] || DEFAULT_RECONNECT_FALLBACK
      })

    let defaultEncode: Encode<void>
    let defaultDecode: Decode<void>

    const vsn = options?.vsn ?? DEFAULT_VSN

    switch (vsn) {
      case VSN_1_0_0:
        defaultEncode = (payload, callback) => {
          return callback(JSON.stringify(payload))
        }
        defaultDecode = (payload, callback) => {
          return callback(JSON.parse(payload as string))
        }
        break
      case VSN_2_0_0:
        defaultEncode = this.serializer.encode.bind(this.serializer)
        defaultDecode = this.serializer.decode.bind(this.serializer)
        break
      default:
        throw new Error(`Unsupported serializer version: ${result.vsn}`)
    }

    result.vsn = vsn
    result.encode = options?.encode ?? defaultEncode
    result.decode = options?.decode ?? defaultDecode

    result.beforeReconnect = this._reconnectAuth.bind(this)

    if (options?.logLevel || options?.log_level) {
      this.logLevel = options.logLevel || options.log_level
      result.params = { ...result.params, log_level: this.logLevel as string }
    }

    // Handle worker setup
    if (this.worker) {
      if (typeof window !== 'undefined' && !window.Worker) {
        throw new Error('Web Worker is not supported')
      }
      this.workerUrl = options?.workerUrl
      result.autoSendHeartbeat = !this.worker
    }

    return result
  }

  /** @internal */
  private async _reconnectAuth() {
    await this._waitForAuthIfNeeded()
    if (!this.isConnected()) {
      this.connect()
    }
  }

  private _createSocketAdapter(): SocketAdapter {
    return new SocketAdapter(this._endPoint, this._socketOptions)
  }

  private async _openActiveSocket() {
    try {
      if (this._beforeTransportConnect) {
        await this._beforeTransportConnect()
      }
      if (this.isConnecting() || this.isDisconnecting() || this.isConnected()) {
        return
      }
      this._setupConnectionHandlers()
      this.socketAdapter.connect()
      this._handleNodeJsRaceCondition()
    } catch (error) {
      const errorMessage = (error as Error).message
      throw new Error(`WebSocket not available: ${errorMessage}`)
    } finally {
      this._openingActive = false
    }
  }

  private _scheduleConnectionRefresh() {
    this._cancelConnectionRefresh()
    if (this.connectionMaxAgeMs <= 0) {
      return
    }
    const jitter =
      this.connectionRefreshJitterMs > 0
        ? Math.floor(Math.random() * this.connectionRefreshJitterMs)
        : 0
    const delay = this.connectionMaxAgeMs + jitter
    this._refreshTimer = setTimeout(() => {
      this._refreshTimer = null
      void this._rotateConnection()
    }, delay)
    this.log('transport', `connection refresh scheduled in ${delay}ms`)
  }

  private _cancelConnectionRefresh() {
    if (this._refreshTimer !== null) {
      clearTimeout(this._refreshTimer)
      this._refreshTimer = null
    }
  }

  private _scheduleRotateRetry() {
    this._cancelRotateRetry()
    this._rotateRetryTimer = setTimeout(() => {
      this._rotateRetryTimer = null
      if (this.isConnected() && !this._rotating) {
        void this._rotateConnection()
      }
    }, CONNECTION_REFRESH_RETRY_MS)
    this.log('transport', `connection refresh retry scheduled in ${CONNECTION_REFRESH_RETRY_MS}ms`)
  }

  private _cancelRotateRetry() {
    if (this._rotateRetryTimer !== null) {
      clearTimeout(this._rotateRetryTimer)
      this._rotateRetryTimer = null
    }
  }

  private async _rotateConnection() {
    if (this._rotating || !this.isConnected() || this.channels.length === 0) {
      return
    }

    this._rotating = true
    this._cutoverStarted = false
    this._cancelConnectionRefresh()
    this.log('transport', 'starting connection refresh')

    try {
      if (this._beforeTransportConnect) {
        await this._beforeTransportConnect()
      }
      if (!this.isConnected() || this.channels.length === 0) {
        throw new Error('active connection lost before standby connect')
      }

      const standby = this._createSocketAdapter()
      this._standbyAdapter = standby
      await this._connectAndWaitOpen(standby)

      const toWarm = this.channels.filter(
        (channel) =>
          channel.joinedOnce &&
          !channel.channelAdapter.isClosed() &&
          !channel.channelAdapter.isLeaving()
      )
      const handles = await Promise.all(toWarm.map((channel) => channel._warmupOn(standby)))

      this._cutover(toWarm, handles, standby)
    } catch (error) {
      this.log('transport', 'connection refresh failed', error)
      await this._teardownStandby()
      this._rotating = false
      this._cutoverStarted = false
      if (this.isConnected() && this.channels.length > 0) {
        this._scheduleRotateRetry()
      }
    }
  }

  private _cutover(
    channels: RealtimeChannel[],
    handles: Awaited<ReturnType<RealtimeChannel['_warmupOn']>>[],
    standby: SocketAdapter
  ) {
    this._cutoverStarted = true
    const outgoing = this.socketAdapter

    for (let i = 0; i < channels.length; i++) {
      channels[i]._adopt(handles[i])
    }

    this.socketAdapter = standby
    this._standbyAdapter = null
    this._setupConnectionHandlers()

    if (this.worker) {
      this._terminateWorker()
      this._startWorkerHeartbeat()
    }

    this._rotating = false
    this._scheduleConnectionRefresh()

    void outgoing.disconnect(() => {}, 1000, 'connection refresh')
    this.log('transport', 'connection refresh complete')
  }

  private async _connectAndWaitOpen(
    adapter: SocketAdapter,
    timeoutMs = STANDBY_CONNECT_TIMEOUT_MS
  ): Promise<void> {
    await new Promise<void>((resolve, reject) => {
      const timer = setTimeout(() => {
        reject(new Error('standby connect timed out'))
      }, timeoutMs)

      adapter.onOpen(() => {
        clearTimeout(timer)
        resolve()
      })
      adapter.onError((error) => {
        clearTimeout(timer)
        reject(error instanceof Error ? error : new Error(String(error)))
      })

      try {
        adapter.connect()
      } catch (error) {
        clearTimeout(timer)
        reject(error)
      }
    })
  }

  private async _teardownStandby() {
    const standby = this._standbyAdapter
    this._standbyAdapter = null
    if (!standby) {
      return
    }
    try {
      await standby.disconnect(() => {}, 1000, 'connection refresh abort')
    } catch {
      // Standby may already be closed.
    }
  }

  private async _abortRotate() {
    this._cancelRotateRetry()
    await this._teardownStandby()
    this._rotating = false
    this._cutoverStarted = false
  }
}
