import RealtimeClient from './RealtimeClient'
import { CLOUDBASE_CONNECTION_MAX_AGE_MS, VSN_1_0_0 } from './lib/constants'
import { wrapReqClassFetch, type AdapterReqClass } from './lib/req-class-fetch'

const COMPONENT_NAME = 'realtime-js'

const AUTH_TOKEN_EVENTS = new Set(['TOKEN_REFRESHED', 'SIGNED_IN', 'INITIAL_SESSION'])

const MISSING_AUTH_HINT =
  '[CloudBase Realtime] 当前没有登录态，无法使用 realtime 能力。\n' +
  '请确认以下各项：\n' +
  '  1 - 是否已调用 app.auth() 初始化认证\n' +
  '  2 - 是否已完成登录（如 auth.signInAnonymously() / auth.signInWithPassword()）\n' +
  '  3 - 登录态是否已过期，需要重新登录'

const warnedMissingAuthApps = new WeakSet<object>()

type GatewayEndPoint = {
  BASE_URL: string
  PROTOCOL: string
}

export type RealtimeAuthChangeEvent =
  | 'SIGNED_OUT'
  | 'SIGNED_IN'
  | 'INITIAL_SESSION'
  | 'TOKEN_REFRESHED'
  | (string & {})

export type RealtimeAuthSession = {
  access_token?: string | null
}

export type RealtimeHostAuth = {
  onAuthStateChange: (
    callback: (event: RealtimeAuthChangeEvent, session: RealtimeAuthSession | null) => void
  ) => unknown
}

type RealtimeHostAuthFactory = ((this: RealtimeHostApp, config?: unknown) => RealtimeHostAuth) &
  Partial<RealtimeHostAuth>

export type RealtimeHostApp = {
  config?: { env?: string }
  request?: {
    getAccessToken?: (token?: string | null) => Promise<string>
  }
  platform?: {
    adapter?: {
      wsClass?: RealtimeClient['socketAdapter']['transport']
      reqClass?: AdapterReqClass
    }
  }
  /**
   * CloudBase Auth。可能是尚未调用的 `app.auth` 工厂，或已经初始化后的 Auth 实例。
   * 未注册 auth 组件时可缺省。
   */
  auth?: RealtimeHostAuthFactory | RealtimeHostAuth
  authInstance?: RealtimeHostAuth
  getEndPointWithKey: (key: string) => GatewayEndPoint
  registerComponent: (component: { name: string; entity: Record<string, unknown> }) => void
}

const clientCache = new WeakMap<object, RealtimeClient>()

/**
 * 从 GATEWAY 端点拼出 CloudBase Realtime WebSocket 基址：
 * `wss://{GW}/v1/realtime`
 *
 * Phoenix Socket 会再补 `/websocket`，最终为：
 * `wss://{GW}/v1/realtime/websocket?apikey={accessToken}&vsn=1.0.0`
 *
 * GATEWAY 的 `BASE_URL` 已含 `/v1`（如 `//{env}.api.tcloudbasegateway.com/v1`）。
 */
export function buildRealtimeEndPoint(app: Pick<RealtimeHostApp, 'getEndPointWithKey'>): string {
  const { BASE_URL, PROTOCOL } = app.getEndPointWithKey('GATEWAY')
  const wsProtocol = /^https:?$/i.test(PROTOCOL) ? 'wss:' : 'ws:'
  const baseUrl = String(BASE_URL || '').replace(/\/+$/, '')
  return `${wsProtocol}${baseUrl}/realtime`
}

function warnMissingRealtimeAuth(app: RealtimeHostApp): void {
  if (warnedMissingAuthApps.has(app)) {
    return
  }
  warnedMissingAuthApps.add(app)
  console.warn(MISSING_AUTH_HINT)
}

async function resolveAccessToken(app: RealtimeHostApp): Promise<string | null> {
  try {
    const token = await app.request?.getAccessToken?.()
    if (token) {
      warnedMissingAuthApps.delete(app)
      return token
    }
  } catch {
    // 与 database / functions 等能力一致：无 auth 或未登录时 getAccessToken 会抛错。
    // realtime 在握手前吞掉该错误，改为提示用户先登录，避免静默用 envId 去连网关。
  }
  warnMissingRealtimeAuth(app)
  return null
}

function isHostAuth(value: unknown): value is RealtimeHostAuth {
  return !!value && typeof (value as RealtimeHostAuth).onAuthStateChange === 'function'
}

/**
 * 只读取已经初始化的 Auth，不调用 `app.auth()`。
 * 提前调用会按默认 persistence 锁死实例，挡住用户稍后传入的配置。
 */
function resolveExistingAuth(app: RealtimeHostApp): RealtimeHostAuth | null {
  try {
    if (isHostAuth(app.auth)) {
      return app.auth
    }
    if (isHostAuth(app.authInstance)) {
      return app.authInstance
    }
  } catch {
    // auth 访问失败时忽略
  }
  return null
}

const boundAuthClients = new WeakSet<RealtimeClient>()
const pendingAuthClients = new WeakMap<RealtimeHostApp, Set<RealtimeClient>>()
const deferredAuthApps = new WeakSet<RealtimeHostApp>()

/**
 * 把 CloudBase Auth 事件推给 Realtime：登录 / 刷新立刻 `setAuth(token)`，登出 `setAuth()`。
 * 对标 supabase-js `SupabaseClient._listenForAuthEvents`。同一 client 只绑定一次。
 */
export function bindRealtimeAuthEvents(client: RealtimeClient, auth: RealtimeHostAuth): void {
  if (boundAuthClients.has(client)) {
    return
  }
  boundAuthClients.add(client)

  let changedAccessToken: string | undefined

  auth.onAuthStateChange((event, session) => {
    const token = session?.access_token ?? undefined
    if (AUTH_TOKEN_EVENTS.has(event) && token && changedAccessToken !== token) {
      changedAccessToken = token
      void client.setAuth(token).catch((e) => {
        client.log('error', 'Error setting auth from auth state change', e)
      })
      return
    }
    if (event === 'SIGNED_OUT') {
      changedAccessToken = undefined
      void client.setAuth().catch((e) => {
        client.log('error', 'Error clearing auth from SIGNED_OUT', e)
      })
    }
  })
}

function bindPendingClients(app: RealtimeHostApp, auth: RealtimeHostAuth): void {
  const pending = pendingAuthClients.get(app)
  if (!pending) {
    return
  }
  for (const client of pending) {
    bindRealtimeAuthEvents(client, auth)
  }
  pending.clear()
  pendingAuthClients.delete(app)
}

function bindOrDeferAuthEvents(app: RealtimeHostApp, client: RealtimeClient): void {
  const existing = resolveExistingAuth(app)
  if (existing) {
    bindRealtimeAuthEvents(client, existing)
    return
  }

  const factory = app.auth
  if (typeof factory !== 'function') {
    return
  }

  let pending = pendingAuthClients.get(app)
  if (!pending) {
    pending = new Set()
    pendingAuthClients.set(app, pending)
  }
  pending.add(client)

  if (deferredAuthApps.has(app)) {
    return
  }
  deferredAuthApps.add(app)

  const wrapped: RealtimeHostAuthFactory = function (this: RealtimeHostApp, config?: unknown) {
    const auth = factory.call(this ?? app, config)
    if (isHostAuth(auth)) {
      bindPendingClients(app, auth)
    }
    return auth
  }

  try {
    Object.defineProperty(app, 'auth', {
      configurable: true,
      enumerable: true,
      writable: true,
      value: wrapped,
    })
  } catch {
    app.auth = wrapped
  }
}

export function createRealtimeClient(app: RealtimeHostApp): RealtimeClient {
  const endPoint = buildRealtimeEndPoint(app)
  const params: { apikey: string } = {
    apikey: app.config?.env || 'cloudbase',
  }

  let client: RealtimeClient
  const applyAccessToken = (token: string | null) => {
    if (token) {
      client.apiKey = token
      params.apikey = token
    }
    return token
  }
  const options: ConstructorParameters<typeof RealtimeClient>[1] = {
    params,
    vsn: VSN_1_0_0,
    accessToken: async () => applyAccessToken(await resolveAccessToken(app)),
    connectionMaxAgeMs: CLOUDBASE_CONNECTION_MAX_AGE_MS,
    beforeTransportConnect: async () => {
      await client.setAuth()
    },
  }

  const wsClass = app.platform?.adapter?.wsClass
  if (wsClass) {
    options.transport = wsClass
  }

  const reqClass = app.platform?.adapter?.reqClass
  if (reqClass) {
    options.fetch = wrapReqClassFetch(reqClass)
  }

  client = new RealtimeClient(endPoint, options)
  bindOrDeferAuthEvents(app, client)

  return client
}

function getOrCreateClient(app: RealtimeHostApp): RealtimeClient {
  const cached = clientCache.get(app)
  if (cached) {
    return cached
  }
  const client = createRealtimeClient(app)
  clientCache.set(app, client)
  return client
}

const component = {
  name: COMPONENT_NAME,
  entity: {
    realtime(this: RealtimeHostApp) {
      return getOrCreateClient(this)
    },
  },
}

declare const cloudbase: Pick<RealtimeHostApp, 'registerComponent'>

try {
  cloudbase.registerComponent(component)
} catch {
  // 尚未挂到全局 cloudbase 时忽略，由 registerRealtimeJs 再注册
}

export function registerRealtimeJs(app: Pick<RealtimeHostApp, 'registerComponent'>): void {
  try {
    app.registerComponent(component)
  } catch (e) {
    console.warn(e)
  }
}

try {
  ;(window as { registerRealtimeJs?: typeof registerRealtimeJs }).registerRealtimeJs =
    registerRealtimeJs
} catch {
  // 非浏览器环境忽略
}
