import { version } from './version'
import type {
  SocketState,
  ChannelState,
  ChannelEvent as PhoenixChannelEvent,
  Transport,
  Vsn,
} from '../phoenix/types'

export type { SocketState, ChannelState, Transport }

export const DEFAULT_VERSION = `realtime-js/${version}`

export const VSN_1_0_0: Vsn = '1.0.0'
export const VSN_2_0_0: Vsn = '2.0.0'
export const DEFAULT_VSN: Vsn = VSN_2_0_0

export const VERSION = version

export const DEFAULT_TIMEOUT = 10000

/** Default CloudBase gateway WebSocket max lifetime used for connection refresh. */
export const CLOUDBASE_CONNECTION_MAX_AGE_MS = 270000

/** Random extra delay added on top of `connectionMaxAgeMs` when scheduling refresh. */
export const DEFAULT_CONNECTION_REFRESH_JITTER_MS = 20000

/** Delay before retrying a failed dual-connection refresh. */
export const CONNECTION_REFRESH_RETRY_MS = 10000

/** How long to wait for the standby socket to open during refresh. */
export const STANDBY_CONNECT_TIMEOUT_MS = 10000

/** Mirrors the Realtime server's own default for `postgres_changes_options.timeout`. */
export const DEFAULT_POSTGRES_CHANGES_WAIT_TIMEOUT = 15000

/**
 * Headroom added to the join timeout when waiting on postgres_changes, covering the
 * CHANNEL_ERROR_BACKOFF_MS sleep (5s by default) the server takes before rejecting a join.
 */
export const POSTGRES_CHANGES_WAIT_ERROR_GRACE = 10000

export const WS_CLOSE_NORMAL = 1000
export const MAX_PUSH_BUFFER_SIZE = 100

export const SOCKET_STATES = {
  connecting: 0,
  open: 1,
  closing: 2,
  closed: 3,
} as const

export const CHANNEL_STATES = {
  closed: 'closed',
  errored: 'errored',
  joined: 'joined',
  joining: 'joining',
  leaving: 'leaving',
} as const

export type ChannelEvent = PhoenixChannelEvent

export const CHANNEL_EVENTS = {
  close: 'phx_close',
  error: 'phx_error',
  join: 'phx_join',
  reply: 'phx_reply',
  leave: 'phx_leave',
} as const

export const TRANSPORTS = {
  websocket: 'websocket',
} as const

export type ConnectionState = 'connecting' | 'open' | 'closing' | 'closed' | (string & {})

export const CONNECTION_STATE = {
  connecting: 'connecting',
  open: 'open',
  closing: 'closing',
  closed: 'closed',
} as const
